import React, { forwardRef, ElementType } from 'react';
import styled from 'styled-components';

import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { SpacingSize } from '../helpers/spacing.js';

/**
 * @deprecated `Columns` component will be removed, use `Flex` or `Grid` instead.
 */
export interface ColumnsContainerProps extends StylingProps, DataTestId {
  /**
   * Gap between each of the children.
   * @defaultValue 8
   */
  gap?: SpacingSize;
}

const defaultColumnsGap = 8;

/** Props used for the Columns component, which consist of ColumnsContainerProps and children. */
export interface ColumnsOwnProps extends WithChildren, ColumnsContainerProps {}

/** Merge own props with others inherited from the underlying element type.
 * @deprecated `Columns` component will be removed, use `Flex` or `Grid` instead.
 */
export type ColumnsProps<E extends ElementType> = PolymorphicComponentProps<
  E,
  ColumnsOwnProps
>;

const StyledColumns = /* @__PURE__ */ styled('div')<{
  $gap?: number;
}>(({ $gap }) => {
  return {
    display: 'flex',
    gap: `${$gap}px`,
  };
});

/**
 * The `Columns` component
 * can be used to wrap `Column` components to create a simple layout
 * Per default, the width of each column is the same and a column gap of 8 px is used.
 * @deprecated `Columns` component will be removed, use `Flex` or `Grid` instead.
 */
export const Columns: <E extends React.ElementType = 'div'>(
  props: ColumnsProps<E>,
) => React.ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends React.ElementType>(
    props: ColumnsProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const {
      children,
      gap = defaultColumnsGap,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: ColumnsProps<E> = props;

    return (
      <StyledColumns
        {...remainingProps}
        ref={forwardedRef}
        data-testid={dataTestId}
        className={consumerClassName}
        style={consumerStyle}
        $gap={gap}
      >
        {children}
      </StyledColumns>
    );
  },
);
